import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // ---- Image Plane ----
  const texture = ctx.textureLoader.load(config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png');
  // Atlas source rect: 0,0,512,320 → aspect 1.6:1
  const aspect = 512 / 320;
  const planeWidth = 4; // scene units, fits within hub frame x[-3.5,3.5]
  const planeHeight = planeWidth / aspect;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    map: texture,
    side: THREE.DoubleSide,
  });
  const imageMesh = new THREE.Mesh(geometry, material);
  group.add(imageMesh);

  // ---- Text Plane (subhead) ----
  // Design token: subhead = 0.2 scene-unit em height
  // Use paper color for contrast (assuming image is dark)
  const textSize = 0.2;
  const textMesh = ctx.fontAtlas.createText(config.textContent, {
    fontFamily: 'Lora',
    fontWeight: 400,
    fontSize: textSize,
    color: '#e8ecf2',
    // no outline or shadow, static composition
  });
  // Position text slightly forward to avoid z-fighting
  textMesh.position.set(0, 0, 0.001);
  // Center horizontally and vertically relative to image (could tweak per design)
  // For now, place at a typical subhead position – slightly above center
  textMesh.position.y = planeHeight * 0.15;
  group.add(textMesh);

  // ---- Scene Placement ----
  if (config.scenePosition) {
    group.position.copy(config.scenePosition);
  }
  if (config.sceneRotation) {
    group.rotation.set(...config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.copy(config.sceneScale);
  } else {
    group.scale.set(1, 1, 1);
  }

  // ---- Event Handlers (none) ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // Dispose font atlas text resources if provided by ctx
    if (textMesh.geometry) textMesh.geometry.dispose();
    if (textMesh.material) textMesh.material.dispose();
  };

  return group;
}
